function mergeLive(rows){const m=new Map(R.live.map(r=>[Math.round(r.timestamp*1000),r]));for(const row of normalizeRows(rows))m.set(Math.round(row.timestamp*1000),row);R.live=[...m.values()].sort((a,b)=>a.timestamp-b.timestamp).slice(-43200)}
