function applyLive(l){R.status.live=l||{};const put=(k,v)=>{if(id(k))id(k).textContent=v};put('o2rLiveSpo2',l.spo2??'–');put('o2rLiveHr',l.heart_rate??'–');put('o2rLiveBattery',l.battery_percent??'–');put('o2rLiveSignal',`jel ${l.signal_strength??'–'}`);put('o2rLiveState',l.calibrating?'Kalibrál':l.measuring?'Mér':l.connected?'Készenlét':'Nincs kapcsolat');put('o2rDeviceName',l.device_model||l.device_name||l.remembered_address||R.settings.o2ring_preferred_address||'O2Ring');const badge=id('o2rStatus');if(badge)badge.textContent=!R.settings.o2ring_ble_enabled?'BLE kikapcsolva':l.connected?(l.measuring?'Mér':'Kapcsolódva'):(l.scanning?'Keresés…':'Nincs kapcsolat');id('o2rConnectNow')?.classList.toggle('hidden',!!l.connected);id('smO2QuickConnect')?.classList.toggle('hidden',!!l.connected)}
