function ensureO2CoreChartDefs(){try{for(const d of O2_FOCUS_DEFS)if(CHART_BY_KEY&&!CHART_BY_KEY[d.key])CHART_BY_KEY[d.key]={key:d.key,title:d.title,color:d.color}}catch{}}
