function overlaySelect(key){const s=document.createElement('select');s.className='sm-o2-overlay-select';s.title='O₂ réteg';s.innerHTML='<option value="off">Alapnézet</option><option value="spo2">SpO₂</option><option value="hr">Pulzus</option><option value="both">SpO₂ + Pulzus</option>';s.value=savedOverlay(key);s.disabled=!R.day?.available;s.onchange=e=>saveOverlay(e.currentTarget.dataset.signal||key,e.currentTarget.value);return s}
function ensureOverlayControls(){const toolbar=q('#dashboardDailyView .hero-head .toolbar');if(toolbar&&!id('smO2OverlayFocus')){const w=document.createElement('label');w.id='smO2OverlayFocus';w.className='sm-o2-overlay-control';w.innerHTML='<span>Réteg</span>';const s=overlaySelect('flow');s.id='smO2OverlayFocusSelect';w.appendChild(s);toolbar.insertBefore(w,id('resetZoom'))}updateFocusOverlayControl();installPerStackOverlayControls();ensureFocusOverlayCanvas()}
function updateFocusOverlayControl(){const s=id('smO2OverlayFocusSelect');if(!s)return;let key='flow';try{key=state.selectedSignal||'flow'}catch{}const virtual=isO2FocusKey(key);id('smO2OverlayFocus')?.classList.toggle('hidden',virtual);s.dataset.signal=key;s.value=savedOverlay(key);s.disabled=!R.day?.available||virtual}
function stackKey(card){const direct=card.dataset.signal||card.dataset.key;if(direct)return direct;const text=card.querySelector('.stack-head')?.textContent||'';for(const[name,key]of Object.entries(signalNameMap))if(text.includes(name))return key;return null}
function installPerStackOverlayControls(){for(const card of qa('#stackedCharts .stack-chart')){if(card.classList.contains('sm-o2-stack'))continue;const key=stackKey(card);if(!key)continue;let s=card.querySelector('.sm-o2-overlay-select');if(!s){s=overlaySelect(key);card.querySelector('.stack-head')?.appendChild(s)}s.dataset.signal=key;s.value=savedOverlay(key);s.disabled=!R.day?.available;card.classList.toggle('sm-has-o2-overlay',s.value!=='off');ensureStackOverlayCanvas(card,key)}}
function ensureFocusOverlayCanvas(){const host=q('#dashboardDailyView .hero-stack');if(!host)return;let c=id('smO2HeroCanvas');if(!c){c=document.createElement('canvas');c.id='smO2HeroCanvas';c.className='canvas-overlay sm-o2-overlay-canvas';c.style.pointerEvents='none';host.appendChild(c)}}
function ensureStackOverlayCanvas(card,key){const host=card.querySelector('.canvas-stack,.stack-canvas');if(!host)return;let c=host.querySelector('.sm-o2-overlay-canvas');if(!c){c=document.createElement('canvas');c.className='canvas-overlay sm-o2-overlay-canvas';c.dataset.signal=key;c.style.pointerEvents='none';host.appendChild(c)}return c}
function drawOverlayScaleLabels(ctx,w,h,p,mode,hrLo,hrHi){ctx.save();ctx.font='9px system-ui';ctx.textAlign='right';if(mode==='spo2'||mode==='both'){ctx.fillStyle=COLORS.spo2;ctx.fillText('O₂ 100%',w-5,p.t+8);ctx.fillText('O₂ 75%',w-5,p.t+(h-p.t-p.b)-2)}if(mode==='hr'||mode==='both'){ctx.fillStyle=COLORS.hr;ctx.fillText(`HR ${hrHi}`,w-5,p.t+(mode==='both'?20:8));ctx.fillText(`HR ${hrLo}`,w-5,p.t+(h-p.t-p.b)-(mode==='both'?14:2))}ctx.restore()}
function drawOverlayCanvas(c,key,mode){if(!c||!visible(c))return;const {ctx,w,h}=chartSize(c,190);ctx.clearRect(0,0,w,h);if(!R.day?.available||mode==='off')return;const rs=normalizeRows(R.day.samples||[]),range=dailyRange();if(!range)return;const[a,b]=range,p={l:54,r:54,t:18,b:32},iw=w-p.l-p.r,ih=h-p.t-p.b,mx=t=>p.l+(t-a)/Math.max(.001,b-a)*iw,gap=Math.max(4,medianDelta(rs)*3.2),hrs=rs.map(r=>num(r.heart_rate)).filter(v=>v!=null),hrLo=hrs.length?Math.max(30,Math.floor(Math.min(...hrs)-6)):40,hrHi=hrs.length?Math.min(220,Math.ceil(Math.max(...hrs)+6)):140,my=(v,lo,hi)=>p.t+(hi-v)/Math.max(.001,hi-lo)*ih;if(mode==='spo2'||mode==='both')drawLine(ctx,makeSegments(rs,'spo2',a,b,gap),mx,v=>my(v,75,100),COLORS.spo2,1.05);if(mode==='hr'||mode==='both')drawLine(ctx,makeSegments(rs,'heart_rate',a,b,gap),mx,v=>my(v,hrLo,hrHi),COLORS.hr,1.05);drawOverlayScaleLabels(ctx,w,h,p,mode,hrLo,hrHi);let ht=null;try{ht=num(state.hoverTime);if(ht&&ht>1e12)ht/=1000}catch{}if(ht&&ht>=a&&ht<=b){const x=mx(ht),r=nearest(rs,ht);ctx.strokeStyle='rgba(235,248,255,.66)';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(x,p.t);ctx.lineTo(x,p.t+ih);ctx.stroke();ctx.setLineDash([]);if(r){const parts=[clock(r.timestamp)];if((mode==='spo2'||mode==='both')&&num(r.spo2)!=null)parts.push(`SpO₂ ${fmt(r.spo2,0)}%`);if((mode==='hr'||mode==='both')&&num(r.heart_rate)!=null)parts.push(`Pulzus ${fmt(r.heart_rate,0)} bpm`);const txt=parts.join('  •  ');ctx.font='10px system-ui';const tw=ctx.measureText(txt).width,tx=Math.max(p.l,Math.min(w-p.r-tw-10,x+8));ctx.fillStyle='rgba(6,15,25,.9)';ctx.fillRect(tx,p.t+4,tw+8,18);ctx.fillStyle='#dff5ff';ctx.fillText(txt,tx+4,p.t+17)}}}
function drawOverlays(){updateFocusOverlayControl();let key='flow';try{key=state.selectedSignal||'flow'}catch{}drawOverlayCanvas(id('smO2HeroCanvas'),key,savedOverlay(key));for(const card of qa('#stackedCharts .stack-chart:not(.sm-o2-stack)')){const k=stackKey(card);if(k)drawOverlayCanvas(card.querySelector('.sm-o2-overlay-canvas'),k,savedOverlay(k))}}
function renderNightCard(){const list=id('nightEvalList');if(!list)return;let c=id('smNightO2Card');if(c&&c.parentElement!==list){c.remove();c=null}if(!c){c=document.createElement('li');c.id='smNightO2Card';c.className='night-fact info sm-night-o2-card';c.dataset.o2ringFeature='1';list.appendChild(c)}const x=R.day;if(!x?.available||!x.summary){c.innerHTML='<span class="night-fact-icon">O₂</span><div><small>Oximetria</small><strong>Nincs illesztett O2Ring adat</strong><em>CPAP-idővel átfedő mérés nem található.</em></div>';return}const s=x.summary||{},spo2=num(s.spo2_median)??num(s.spo2_average),hr=num(s.heart_rate_median)??num(s.heart_rate_average),parts=[];if(spo2!=null)parts.push(`SpO₂ ${fmt(spo2,1)}%`);if(hr!=null)parts.push(`Pulzus ${fmt(hr,1)} bpm`);c.innerHTML=`<span class="night-fact-icon">O₂</span><div><small>Oximetria</small><strong>${parts.length?parts.join(' • '):'Nincs értékelhető adat'}</strong><em>Medián • CPAP-idővel átfedő O2Ring adat</em></div>`}
function drawDashboardO2Mini(){const rows=R.dashboardTrendRows||[],range=R.dashboardTrendZoom||bounds(rows),set=v=>R.dashboardTrendZoom=v,reset=()=>R.dashboardTrendZoom=null,redraw=drawDashboardO2Mini,defs=[['smDashO2Trend',[{key:'spo2',label:'SpO₂',unit:'%',color:COLORS.spo2,fixed:[75,100]}]],['smDashHrTrend',[{key:'heart_rate',label:'Pulzus',unit:' bpm',color:COLORS.hr}]]];for(const[cid,ss]of defs){const c=id(cid);chartDraw(c,rows,{range,series:ss,syncGroup:'dash-o2',rightAxis:false,trendGap:true,gapSeconds:36*3600,xLabel:date,tooltipLabel:ts=>`${date(ts)} ${clock(ts)}`,redraw});bindChart(c,{setRange:set,resetRange:reset,redraw,syncGroup:'dash-o2'})}}
function ensureDashboardO2Section(){const agg=q('#dashboardOverviewView .aggregate-cards');if(!agg)return null;let sec=id('smDashboardO2V534');if(!sec){sec=document.createElement('section');sec.id='smDashboardO2V534';sec.className='panel sm-dashboard-o2-v534';sec.dataset.o2ringFeature='1';sec.innerHTML='<div class="panel-head"><div><h3>Oximetriai összegzés</h3><span>CPAP-idővel átfedő O2Ring-adatok.</span></div><button id="smDashO2Open">Oximetria →</button></div><div class="sm-dashboard-o2-cards"><div><span>Medián SpO₂</span><b id="smDashO2Avg">—</b></div><div><span>Minimum SpO₂</span><b id="smDashO2Min">—</b></div><div><span>Medián pulzus</span><b id="smDashHrAvg">—</b></div><div><span>Átlag T90</span><b id="smDashT90">—</b></div></div><div class="sm-dashboard-o2-mini"><article><header>SpO₂ trend</header><div class="sm-o2-chart-wrap"><canvas id="smDashO2Trend"></canvas></div></article><article><header>Pulzus trend</header><div class="sm-o2-chart-wrap"><canvas id="smDashHrTrend"></canvas></div></article></div><div id="smDashO2Empty" class="o2r-empty hidden">Ebben az időszakban még nincs illesztett O2Ring adat.</div>';agg.insertAdjacentElement('afterend',sec);id('smDashO2Open').onclick=()=>openOximetry('recordings')}return sec}
function dayTrendTs(code){const s=String(code||'');if(!/^\d{8}$/.test(s))return null;return Date.UTC(Number(s.slice(0,4)),Number(s.slice(4,6))-1,Number(s.slice(6,8)),12)/1000}
async function refreshDashboardO2(force=false){const sec=ensureDashboardO2Section();if(!sec)return;let rows=[];try{rows=state.dashboardOverview?.rows||[]}catch{}if(!rows.length){R.dashboardTrendRows=[];id('smDashO2Empty')?.classList.remove('hidden');drawDashboardO2Mini();return}const data=await getBatch(rows.map(r=>r.day),force),avail=data.filter(x=>x.available&&x.summary).sort((a,b)=>String(a.day).localeCompare(String(b.day))),av=key=>{const v=avail.map(x=>num(x.summary?.[key])).filter(x=>x!=null);return v.length?v.reduce((a,b)=>a+b,0)/v.length:null},mins=avail.map(x=>num(x.summary?.spo2_minimum)).filter(x=>x!=null),spo2Med=av('spo2_median')??av('spo2_average'),hrMed=av('heart_rate_median')??av('heart_rate_average');id('smDashO2Avg').textContent=spo2Med==null?'—':`${fmt(spo2Med,1)}%`;id('smDashO2Min').textContent=mins.length?`${Math.min(...mins)}%`:'—';id('smDashHrAvg').textContent=hrMed==null?'—':`${fmt(hrMed,1)} bpm`;id('smDashT90').textContent=av('t90_seconds')==null?'—':dur(av('t90_seconds'));id('smDashO2Empty').classList.toggle('hidden',avail.length>0);R.dashboardTrendRows=avail.map((x,i)=>({timestamp:num(x.matches?.[0]?.cpap_start)||dayTrendTs(x.day)||Date.now()/1000+i*86400,spo2:num(x.summary?.spo2_median)??num(x.summary?.spo2_average),heart_rate:num(x.summary?.heart_rate_median)??num(x.summary?.heart_rate_average)}));if(force)R.dashboardTrendZoom=null;drawDashboardO2Mini()}
async function loadRecordings(){const root=id('o2rRecordingList');if(!root)return;root.innerHTML='<div class="o2r-empty">Betöltés…</div>';try{const x=await api('/api/o2ring/recordings'),rows=x.rows||[];root.innerHTML=rows.length?rows.map(r=>{const s=r.summary||{};return `<button class="o2r-recording-row" data-rid="${esc(r.recording_id)}"><div><b>${date(r.start_ts)}</b><small>${clock(r.start_ts)} – ${clock(r.end_ts)}</small></div><div><small>SpO₂ átlag</small><b>${fmt(s.spo2_average,1)}%</b></div><div><small>Minimum</small><b>${fmt(s.spo2_minimum,0)}%</b></div><div><small>T90</small><b>${dur(s.t90_seconds)}</b></div><div><small>Pulzus</small><b>${fmt(s.heart_rate_average,0)}</b></div><span>›</span></button>`}).join(''):'<div class="o2r-empty">Még nincs letöltött O2Ring felvétel.</div>';qa('[data-rid]',root).forEach(b=>b.onclick=()=>openRecording(b.dataset.rid))}catch(e){root.innerHTML=`<div class="o2r-empty">${esc(e.message)}</div>`}}
async function openRecording(rid){try{const x=await api(`/api/o2ring/recording?id=${encodeURIComponent(rid)}&max_points=16000`);R.recording=x;R.recordingZoom=null;const p=id('o2rRecordingDetail'),s=x.summary||{};p.classList.remove('hidden');p.innerHTML=`<div class="panel-head"><div><h3>${date(x.start_ts)} • Oximetria</h3><span>${clock(x.start_ts)} – ${clock(x.end_ts)}</span></div><button id="o2rRecReset">Teljes idő</button></div><div class="o2r-daily-cards"><div><span>Átlag SpO₂</span><b>${fmt(s.spo2_average,1)}%</b></div><div><span>Minimum</span><b>${fmt(s.spo2_minimum,0)}%</b></div><div><span>T90</span><b>${dur(s.t90_seconds)}</b></div><div><span>ODI3 / ODI4</span><b>${fmt(s.odi3,1)} / ${fmt(s.odi4,1)}</b></div><div><span>Pulzus</span><b>${fmt(s.heart_rate_average,0)} bpm</b></div></div><div class="o2r-chart-grid"><article class="panel o2r-chart wide"><h4>SpO₂ + pulzus</h4><div class="sm-o2-chart-wrap"><canvas id="o2rRecDual"></canvas></div></article><article class="panel o2r-chart"><h4>SpO₂</h4><div class="sm-o2-chart-wrap"><canvas id="o2rRecSpo2"></canvas></div></article><article class="panel o2r-chart"><h4>Pulzus</h4><div class="sm-o2-chart-wrap"><canvas id="o2rRecHr"></canvas></div></article></div>`;id('o2rRecReset').onclick=()=>{R.recordingZoom=null;drawRecording()};drawRecording();p.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){message(e.message)}}
function drawRecording(){const rs=R.recording?.samples||[],range=R.recordingZoom||bounds(rs),set=v=>R.recordingZoom=v,reset=()=>R.recordingZoom=null,redraw=drawRecording,dual=[{key:'spo2',label:'SpO₂',unit:'%',color:COLORS.spo2,fixed:[75,100]},{key:'heart_rate',label:'Pulzus',unit:' bpm',color:COLORS.hr,axis:'right'}];for(const[cid,ss]of[['o2rRecDual',dual],['o2rRecSpo2',[dual[0]]],['o2rRecHr',[{...dual[1],axis:'left'}]]]){const c=id(cid);chartDraw(c,rs,{range,series:ss,syncGroup:'recording',redraw});bindChart(c,{setRange:set,resetRange:reset,redraw,syncGroup:'recording'})}}
