async function loadTrends(limit=30){if(Number(limit)!==Number(R.trendLimit))R.trendZoom=null;R.trendLimit=limit;try{const x=await api(`/api/o2ring/trends?limit=${limit}`),rows=x.rows||[],t=rows.map(r=>({timestamp:num(r.start_ts),spo2_avg:num(r.summary?.spo2_average),spo2_min:num(r.summary?.spo2_minimum),hr:num(r.summary?.heart_rate_average),t90:num(r.summary?.t90_seconds)/60,odi3:num(r.summary?.odi3),odi4:num(r.summary?.odi4)})).filter(r=>r.timestamp),av=k=>{const v=t.map(r=>num(r[k])).filter(x=>x!=null);return v.length?v.reduce((a,b)=>a+b,0)/v.length:null};R.trendRows=t;id('o2rTrendAvg').textContent=av('spo2_avg')==null?'—':`${fmt(av('spo2_avg'),1)}%`;const mins=t.map(r=>r.spo2_min).filter(x=>x!=null);id('o2rTrendMin').textContent=mins.length?`${Math.min(...mins)}%`:'—';id('o2rTrendHrAvg').textContent=av('hr')==null?'—':`${fmt(av('hr'),1)} bpm`;id('o2rTrendT90Avg').textContent=av('t90')==null?'—':`${fmt(av('t90'),0)} p`;id('o2rTrendEmpty').classList.toggle('hidden',t.length>=2);drawTrendCharts()}catch{R.trendRows=[];drawTrendCharts()}}
function ensureReportColumns(){const table=q('.report-days-table'),head=table?.querySelector('thead tr'),body=id('reportDaysBody');if(!table||!head||!body)return false;table.closest('.table-panel')?.classList.add('sm-report-days-compact');for(const[k,l]of[['spo2avg','SpO₂ átlag'],['spo2min','SpO₂ min.'],['hravg','Pulzus átlag'],['t90','T90'],['odi','ODI3 / ODI4']])if(!head.querySelector(`[data-sm-o2-col="${k}"]`)){const th=document.createElement('th');th.dataset.smO2Col=k;th.textContent=l;head.appendChild(th)}return true}
async function hydrateReport(force=false){if(!ensureReportColumns())return;const body=id('reportDaysBody'),rows=qa('tr.report-row[data-day]',body);if(!rows.length){const td=body.querySelector('td[colspan]');if(td)td.colSpan=Math.max(Number(td.colSpan)||8,13);return}for(const tr of rows)for(const k of['spo2avg','spo2min','hravg','t90','odi'])if(!tr.querySelector(`[data-sm-o2-cell="${k}"]`)){const td=document.createElement('td');td.dataset.smO2Cell=k;td.textContent='—';tr.appendChild(td)}const data=await getBatch(rows.map(r=>r.dataset.day),force),map=new Map(data.map(x=>[String(x.day),x]));for(const tr of rows){const s=map.get(String(tr.dataset.day))?.summary,put=(k,v)=>{const e=tr.querySelector(`[data-sm-o2-cell="${k}"]`);if(e)e.textContent=v};put('spo2avg',s?`${fmt(s.spo2_average,1)}%`:'—');put('spo2min',s?`${fmt(s.spo2_minimum,0)}%`:'—');put('hravg',s?fmt(s.heart_rate_average,1):'—');put('t90',s?dur(s.t90_seconds):'—');put('odi',s?`${fmt(s.odi3,1)} / ${fmt(s.odi4,1)}`:'—')}}
